StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_PVSelect                                                                                                                                                                                                                                                                       
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-03-05		William Veim			Initial release
//	1.0.1				2025-11-04		William Veim			Added override PV select index
//	1.0.2				2025-11-12		William Veim			Bugfix change PV value
//	1.0.3				2026-02-21		William Veim			Updated according to new quality states
//	1.0.4				2026-03-03		William Veim			Updated to not be affected by analog alarms (Low low, low, high, high high)
//
//==============================================================================================================================
//
// 		FUNCTIONALITY:
// 		Retrieves the desired process value based on user input and/or failure of the current sensor
//
//==============================================================================================================================

(*************************************************************************
 *	INITIALIZE
 *************************************************************************)
 
PV_NumberUsed:=0;
PV_Select:=LIMIT(MN:=UINT#0, In:=PV_Select, MX:=UINT#4);
PV_NotAvailable:=FALSE;

//Counting number of PV in use
PV_InUse_CNT.Bit[0]:=PV_Value1_Index>0;
PV_InUse_CNT.Bit[1]:=PV_Value2_Index>0;
PV_InUse_CNT.Bit[2]:=PV_Value3_Index>0;
PV_InUse_CNT.Bit[3]:=PV_Value4_Index>0;
PV_InUse_CNT.Bit[4]:=PV_Value5_Index>0;

PV_NumberUsed:= BitCnt(In:=PV_InUse_CNT.Wrd);
PV_OnlyOneUsed:=PV_NumberUsed = 1;
PV_MultipleUsed:=PV_NumberUsed > 1;
 
(*************************************************************************
 *	UPDATING INPUT VARAIBELS TO INTERNAL ARRAY
 *************************************************************************)

//Retrives information for selected PV
CASE PV_Select OF

	0://PV value 1
	HE_AnaExdToAnaSimp(AnalogValue:=EXT_AnalogValue[PV_Value1_Index], AnalogValueSimplified:=PV_Actual);
	PV_Actual_Y0:=	EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.ProcessValue_SensorMin;
	PV_Actual_Y1:=	EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.ProcessValue_SensorMax;
	IF  PV_Value1_Index = 0 OR (PV_AutoSwitch AND
		(EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_5.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_5.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_5.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_6.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_6.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_6.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_7.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_7.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_7.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_8.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_8.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_8.Sts_Visible)		
		OR (EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_9.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_9.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_9.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_10.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_10.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_10.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_11.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_11.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_11.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_12.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_12.Sts_State AND EXT_AnalogValue[PV_Value1_Index].EXT_Engineering.StateCfg_12.Sts_Visible)) THEN
		PV_FindNew := TRUE;
	END_IF;
	
	1://PV value 2
	HE_AnaExdToAnaSimp(AnalogValue:=EXT_AnalogValue[PV_Value2_Index], AnalogValueSimplified:=PV_Actual);
	PV_Actual_Y0:=	EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.ProcessValue_SensorMin;
	PV_Actual_Y1:=	EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.ProcessValue_SensorMax;
	IF  PV_Value2_Index = 0 OR (PV_AutoSwitch AND
		(EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_5.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_5.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_5.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_6.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_6.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_6.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_7.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_7.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_7.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_8.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_8.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_8.Sts_Visible)		
		OR (EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_9.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_9.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_9.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_10.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_10.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_10.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_11.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_11.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_11.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_12.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_12.Sts_State AND EXT_AnalogValue[PV_Value2_Index].EXT_Engineering.StateCfg_12.Sts_Visible)) THEN
		PV_FindNew := TRUE;
	END_IF;
	
	2://PV value 3
	HE_AnaExdToAnaSimp(AnalogValue:=EXT_AnalogValue[PV_Value3_Index], AnalogValueSimplified:=PV_Actual);
	PV_Actual_Y0:=	EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.ProcessValue_SensorMin;
	PV_Actual_Y1:=	EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.ProcessValue_SensorMax;
	IF  PV_Value3_Index = 0 OR (PV_AutoSwitch AND
		(EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_5.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_5.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_5.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_6.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_6.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_6.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_7.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_7.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_7.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_8.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_8.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_8.Sts_Visible)		
		OR (EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_9.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_9.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_9.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_10.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_10.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_10.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_11.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_11.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_11.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_12.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_12.Sts_State AND EXT_AnalogValue[PV_Value3_Index].EXT_Engineering.StateCfg_12.Sts_Visible)) THEN
		PV_FindNew := TRUE;
	END_IF;
	
	3://PV value 4
	HE_AnaExdToAnaSimp(AnalogValue:=EXT_AnalogValue[PV_Value4_Index], AnalogValueSimplified:=PV_Actual);
	PV_Actual_Y0:=	EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.ProcessValue_SensorMin;
	PV_Actual_Y1:=	EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.ProcessValue_SensorMax;
	IF  PV_Value4_Index = 0 OR (PV_AutoSwitch AND
		(EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_5.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_5.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_5.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_6.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_6.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_6.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_7.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_7.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_7.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_8.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_8.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_8.Sts_Visible)		
		OR (EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_9.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_9.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_9.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_10.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_10.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_10.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_11.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_11.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_11.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_12.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_12.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_12.Sts_Visible)) THEN
		PV_FindNew := TRUE;
	END_IF;
	
	4://PV value 5
	HE_AnaExdToAnaSimp(AnalogValue:=EXT_AnalogValue[PV_Value5_Index], AnalogValueSimplified:=PV_Actual);
	PV_Actual_Y0:=	EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.ProcessValue_SensorMin;
	PV_Actual_Y1:=	EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.ProcessValue_SensorMax;
	IF  PV_Value5_Index = 0 OR (PV_AutoSwitch AND
		(EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_5.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_5.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_5.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_6.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_6.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_6.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_7.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_7.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_7.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_8.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_8.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_8.Sts_Visible)		
		OR (EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_9.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_9.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_9.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_10.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_10.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_10.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_11.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_11.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_11.Sts_Visible)
		OR (EXT_AnalogValue[PV_Value5_Index].EXT_Engineering.StateCfg_12.Cfg_Quality > PV_AutoSwitchState AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_12.Sts_State AND EXT_AnalogValue[PV_Value4_Index].EXT_Engineering.StateCfg_12.Sts_Visible)) THEN
		PV_FindNew := TRUE;
	END_IF;
	
END_CASE;

//FIND NEW PROCESS VALUE
//Looks for quality "Good" or "Diagnostic" (Needs improvement!)
IF PV_FindNew THEN
		IF (EXT_AnalogValue[PV_Value1_Index].EXT_General.Sts_Quality = 6) AND PV_Value1_Index > 0 THEN
			PV_Select := 0;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value2_Index].EXT_General.Sts_Quality = 6) AND PV_Value2_Index > 0 THEN
			PV_Select := 1;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value3_Index].EXT_General.Sts_Quality = 6) AND PV_Value3_Index > 0 THEN
			PV_Select := 2;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value4_Index].EXT_General.Sts_Quality = 6) AND PV_Value4_Index > 0 THEN
			PV_Select := 3;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value5_Index].EXT_General.Sts_Quality = 6) AND PV_Value5_Index > 0 THEN
			PV_Select := 4;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value1_Index].EXT_General.Sts_Quality = 0) AND PV_Value1_Index > 0 THEN
			PV_Select := 0;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value2_Index].EXT_General.Sts_Quality = 0) AND PV_Value2_Index > 0 THEN
			PV_Select := 1;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value3_Index].EXT_General.Sts_Quality = 0) AND PV_Value3_Index > 0 THEN
			PV_Select := 2;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value4_Index].EXT_General.Sts_Quality = 0) AND PV_Value4_Index > 0 THEN
			PV_Select := 3;
			PV_FindNew := FALSE;
		ELSIF (EXT_AnalogValue[PV_Value5_Index].EXT_General.Sts_Quality = 0) AND PV_Value5_Index > 0 THEN
			PV_Select := 4;
			PV_FindNew := FALSE;
		ELSE
			PV_NotAvailable:=TRUE;
		END_IF;
END_IF;
